## Трек Трек С помощью свойства  `hasTrack`  можно управлять отображением фоновой дуги: ```tsx
import React from 'react';
import { ProgressBarCircular } from '@salutejs/sdds-finai';

export function App() {
    return (
        <div style={{ display: 'flex', alignItems: 'center', gap: '1rem' }}>
            <ProgressBarCircular value={50} hasTrack={false} />
            <ProgressBarCircular value={50} />
        </div>
    );
}
```

## Толщина обводки Толщина обводки С помощью свойства  `strokeSize`  можно задать толщину линии прогресса: ```tsx
import React from 'react';
import { ProgressBarCircular } from '@salutejs/sdds-finai';

export function App() {
    return (
        <div style={{ display: 'flex', alignItems: 'center', gap: '1rem' }}>
            <ProgressBarCircular value={50} strokeSize={2} />
            <ProgressBarCircular value={50} strokeSize={4} />
            <ProgressBarCircular value={50} strokeSize={8} />
            <ProgressBarCircular value={50} strokeSize={12} />
        </div>
    );
}
```

## Максимальное значение Максимальное значение По умолчанию прогресс считается из  `maxValue={100}` . Свойство  `maxValue`  позволяет задать произвольный максимум: ```tsx
import React from 'react';
import { ProgressBarCircular } from '@salutejs/sdds-finai';

export function App() {
    return (
        <div style={{ display: 'flex', alignItems: 'center', gap: '1rem' }}>
            <ProgressBarCircular value={25} maxValue={50} size="xl">25/50</ProgressBarCircular>
            <ProgressBarCircular value={75} maxValue={150} size="xl">75/150</ProgressBarCircular>
        </div>
    );
}
```

## Обратное направление Обратное направление С помощью свойства  `reverse`  можно изменить направление заполнения дуги — прогресс будет убывать по часовой стрелке: ```tsx
import React from 'react';
import { ProgressBarCircular } from '@salutejs/sdds-finai';

export function App() {
    return (
        <div style={{ display: 'flex', alignItems: 'center', gap: '1rem' }}>
            <ProgressBarCircular value={75} size="xl">Обычный</ProgressBarCircular>
            <ProgressBarCircular value={75} size="xl" reverse>Обратный</ProgressBarCircular>
        </div>
    );
}
```

## Контент внутри Контент внутри Через  `children`  можно отобразить текст, число, иконку или любой другой контент в центре индикатора: ```tsx
import React from 'react';
import { ProgressBarCircular } from '@salutejs/sdds-finai';

export function App() {
    return (
        <div style={{ display: 'flex', alignItems: 'center', gap: '1rem' }}>
            <ProgressBarCircular value={25} size="xl">25%</ProgressBarCircular>
            <ProgressBarCircular value={50} size="xl">50%</ProgressBarCircular>
            <ProgressBarCircular value={75} size="xl">75%</ProgressBarCircular>
        </div>
    );
}
```

